CREATE OR REPLACE FUNCTION public.workspace_build_item_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.version <> 1 OR NEW.created_at <> NEW.updated_at THEN RAISE EXCEPTION 'invalid initial builder version/time'; END IF;
  ELSE
    IF NEW.id <> OLD.id OR NEW.user_id <> OLD.user_id OR NEW.project_id <> OLD.project_id
      OR NEW.created_at <> OLD.created_at OR NEW.version <> OLD.version + 1 OR NEW.updated_at < OLD.updated_at
    THEN RAISE EXCEPTION 'invalid builder ownership/version/time change'; END IF;
    IF TG_TABLE_NAME = 'workspace_course_lessons' AND to_jsonb(NEW)->>'module_id' IS DISTINCT FROM to_jsonb(OLD)->>'module_id'
    THEN RAISE EXCEPTION 'lesson parent is immutable'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.workspace_build_positions_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent uuid; n bigint; first_position integer; last_position integer;
BEGIN
  IF TG_TABLE_NAME = 'workspace_course_modules' THEN
    IF TG_OP = 'DELETE' THEN parent := OLD.project_id; ELSE parent := NEW.project_id; END IF;
    SELECT count(*), min(position), max(position) INTO n, first_position, last_position FROM workspace_course_modules WHERE project_id = parent;
  ELSE
    IF TG_OP = 'DELETE' THEN parent := OLD.module_id; ELSE parent := NEW.module_id; END IF;
    SELECT count(*), min(position), max(position) INTO n, first_position, last_position FROM workspace_course_lessons WHERE module_id = parent;
  END IF;
  IF n > 0 AND (first_position <> 0 OR last_position <> n - 1) THEN RAISE EXCEPTION 'builder positions must be contiguous'; END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.workspace_build_project_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE s workspace_course_submissions%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'course project identity is immutable'; END IF;
  SELECT * INTO s FROM workspace_course_submissions WHERE id = NEW.approved_submission_id FOR SHARE;
  IF s.id IS NULL OR s.review_status <> 'approved' OR s.review_completed_at IS NULL
    OR s.user_id <> NEW.user_id OR s.creator_profile_id <> NEW.creator_profile_id OR s.draft_id <> NEW.draft_id
    OR NEW.version <> 1 OR NEW.created_at <> NEW.updated_at OR NEW.created_at < s.review_completed_at
    OR NOT EXISTS (SELECT 1 FROM workspace_course_review_events e WHERE e.submission_id = s.id
      AND e.action = 'approved' AND e.to_status = 'approved' AND e.transition_version = s.version AND e.created_at = s.review_completed_at)
  THEN RAISE EXCEPTION 'authoritative owned approval required'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.workspace_check_course_review_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE s workspace_course_submissions%ROWTYPE; e workspace_course_review_events%ROWTYPE;
BEGIN
  IF TG_TABLE_NAME = 'workspace_course_review_events' THEN
    SELECT * INTO s FROM workspace_course_submissions WHERE id = NEW.submission_id;
    IF s.version < NEW.transition_version OR
      (NEW.to_status = 'under_review' AND s.review_started_at IS DISTINCT FROM NEW.created_at) OR
      (NEW.to_status <> 'under_review' AND (s.review_status <> NEW.to_status OR s.review_completed_at IS DISTINCT FROM NEW.created_at)) THEN
      RAISE EXCEPTION 'Workspace event lacks its lifecycle transition' USING ERRCODE = '23514';
    END IF;
  ELSE
    SELECT * INTO e FROM workspace_course_review_events WHERE submission_id = NEW.id AND transition_version = NEW.version;
    IF e.id IS NULL OR e.from_status <> OLD.review_status OR e.to_status <> NEW.review_status OR e.created_at IS DISTINCT FROM NEW.updated_at THEN
      RAISE EXCEPTION 'Workspace transition lacks its audit event' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.workspace_coupon_influencer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM id FROM users WHERE id=NEW.created_by AND role='admin' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Persisted admin required' USING ERRCODE='23514'; END IF;
 IF NEW.source_type='influencer' AND NEW.influencer_id IS NULL THEN RAISE EXCEPTION 'New influencer coupon requires stable identity' USING ERRCODE='23514'; END IF;
 IF NEW.influencer_id IS NOT NULL THEN
   PERFORM id FROM workspace_influencers WHERE id=NEW.influencer_id AND status='active' FOR SHARE;
   IF NOT FOUND OR NEW.source_type<>'influencer' THEN RAISE EXCEPTION 'Active influencer required' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_coupon_paid_evidence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c workspace_coupons; o workspace_membership_orders;
BEGIN
 PERFORM id FROM users WHERE id=NEW.user_id FOR UPDATE;
 SELECT * INTO c FROM workspace_coupons WHERE id=NEW.coupon_id FOR UPDATE;
 IF TG_OP='INSERT' THEN
   IF c.influencer_id IS NOT NULL THEN
     PERFORM id FROM workspace_influencers WHERE id=c.influencer_id AND status='active' FOR SHARE;
     IF NOT FOUND THEN RAISE EXCEPTION 'Influencer campaign paused' USING ERRCODE='23514'; END IF;
   END IF;
 END IF;
 IF NEW.status='redeemed' THEN
   SELECT * INTO o FROM workspace_membership_orders WHERE id=NEW.membership_order_id FOR UPDATE;
   IF o.financial_state<>'captured' OR o.paid_at IS NULL OR o.activation_state='held_for_review' OR NOT EXISTS (
     SELECT 1 FROM workspace_payment_attempts p WHERE p.membership_order_id=o.id AND p.winner
     AND p.provider_payment_id=o.winning_payment_id AND p.state='captured' AND p.amount_paise=o.total_paise
     AND p.currency=o.currency AND p.captured_at=o.paid_at AND p.capture_time_source IS NOT NULL
   ) THEN RAISE EXCEPTION 'Paid redemption requires authoritative eligible capture' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_email_contact_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF lower(btrim(NEW.email)) IS DISTINCT FROM lower(btrim(OLD.email)) THEN
  UPDATE workspace_verified_emails SET active=false,revoked_at=clock_timestamp() WHERE user_id=NEW.id AND active;
  UPDATE workspace_email_challenges SET state='superseded' WHERE user_id=NEW.id AND state IN ('sending','accepted','uncertain');
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_email_notice_bind()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE owner uuid; proof uuid; contact text;
BEGIN
 SELECT user_id INTO owner FROM workspace_membership_orders WHERE id=NEW.membership_order_id;
 SELECT lower(btrim(email)) INTO contact FROM users WHERE id=owner FOR SHARE;
 SELECT id INTO proof FROM workspace_verified_emails WHERE user_id=owner AND email=contact AND active AND verified_at<=clock_timestamp();
 INSERT INTO workspace_email_notice_bindings(notice_id,verification_id) VALUES(NEW.id,proof);
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_email_order_required()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE contact text;
BEGIN
 SELECT lower(btrim(email)) INTO contact FROM users WHERE id=NEW.user_id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM workspace_verified_emails WHERE user_id=NEW.user_id AND email=contact AND active AND verified_at<=clock_timestamp()) THEN
  RAISE EXCEPTION 'Current verified Workspace email required for new order' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_email_proof_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c workspace_email_challenges; contact text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Email ownership history is retained' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-ARRAY['active','revoked_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['active','revoked_at']) OR NOT OLD.active OR NEW.active OR NEW.revoked_at IS NULL THEN
   RAISE EXCEPTION 'Only email proof revocation is allowed' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT lower(btrim(email)) INTO contact FROM users WHERE id=NEW.user_id FOR UPDATE;
  SELECT * INTO c FROM workspace_email_challenges WHERE id=NEW.challenge_id;
  IF c.id IS NULL OR c.user_id<>NEW.user_id OR c.email<>NEW.email OR contact IS DISTINCT FROM NEW.email OR c.state<>'consumed' OR c.consumed_at IS DISTINCT FROM NEW.verified_at OR NOT NEW.active THEN
   RAISE EXCEPTION 'Email proof requires consumed account-bound challenge' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_grant_complete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE g workspace_access_grants; e workspace_access_grant_events; target_grant uuid;
BEGIN
 IF TG_TABLE_NAME='workspace_access_grants' THEN target_grant:=NEW.id;
 ELSIF TG_TABLE_NAME='workspace_access_grant_events' THEN target_grant:=NEW.grant_id;
 ELSE RAISE EXCEPTION 'Unsupported grant completion table' USING ERRCODE='23514'; END IF;
 SELECT * INTO g FROM workspace_access_grants WHERE id=target_grant;
 SELECT * INTO e FROM workspace_access_grant_events WHERE grant_id=g.id AND action='granted';
 IF e.id IS NULL OR e.user_id<>g.user_id OR e.actor_id<>g.granted_by OR e.reason<>g.reason OR e.request_key<>g.request_key OR e.payload_hash<>g.payload_hash OR e.created_at<>g.created_at THEN RAISE EXCEPTION 'Grant and matching audit must commit together' USING ERRCODE='23514'; END IF;
 IF g.status<>'active' AND NOT EXISTS(SELECT 1 FROM workspace_access_grant_events WHERE grant_id=g.id AND action=g.status AND actor_id=g.closed_by AND reason=g.close_reason AND created_at=g.closed_at) THEN RAISE EXCEPTION 'Grant closure needs durable audit' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM workspace_access_grant_events WHERE grant_id=g.id AND action<>'granted' AND (action<>g.status OR actor_id<>g.closed_by OR reason<>g.close_reason OR created_at<>g.closed_at)) THEN RAISE EXCEPTION 'Audit must match grant transition' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_grant_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actor uuid; owner uuid; a workspace_eligibility_attempts; t workspace_creator_terms_versions;
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'Grant history is retained' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='workspace_access_grant_events' THEN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Grant events are immutable' USING ERRCODE='23514'; END IF;
  actor:=NEW.actor_id; owner:=NEW.user_id;
 ELSE
  actor:=CASE WHEN TG_OP='INSERT' THEN NEW.granted_by ELSE NEW.closed_by END; owner:=NEW.user_id;
  IF TG_OP='UPDATE' AND (OLD.status<>'active' OR NEW.status NOT IN ('expired','revoked') OR
   (to_jsonb(NEW)-ARRAY['status','closed_at','closed_by','close_reason']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['status','closed_at','closed_by','close_reason'])) THEN
   RAISE EXCEPTION 'Grant terms are immutable' USING ERRCODE='23514';
  END IF;
 END IF;
 PERFORM id FROM users WHERE id IN (actor,owner) ORDER BY id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM users WHERE id=actor AND role='admin') THEN RAISE EXCEPTION 'Persisted administrator required' USING ERRCODE='42501'; END IF;
 IF TG_TABLE_NAME='workspace_access_grants' AND TG_OP='INSERT' THEN
  IF NEW.status<>'active' OR NEW.created_at>clock_timestamp() OR NEW.created_at<clock_timestamp()-interval '1 minute' THEN RAISE EXCEPTION 'Invalid grant creation' USING ERRCODE='23514'; END IF;
  SELECT * INTO a FROM workspace_eligibility_attempts WHERE id=NEW.eligibility_attempt_id;
  SELECT * INTO t FROM workspace_creator_terms_versions WHERE is_current;
  IF a.user_id IS DISTINCT FROM owner OR a.result<>'eligible' OR a.eligible_until<=NEW.starts_at OR
   a.id IS DISTINCT FROM (SELECT id FROM workspace_eligibility_attempts WHERE user_id=owner ORDER BY decided_at DESC,id DESC LIMIT 1) OR
   NOT EXISTS(SELECT 1 FROM workspace_eligibility_settings WHERE id=a.settings_id AND is_current) OR
   NOT EXISTS(SELECT 1 FROM workspace_policy_versions WHERE id=a.policy_id AND is_current) OR
   t.terms_version IS DISTINCT FROM NEW.terms_version OR t.content_hash IS DISTINCT FROM NEW.terms_content_hash OR t.effective_at>NEW.created_at OR
   NOT EXISTS(SELECT 1 FROM workspace_creator_profiles WHERE id=NEW.creator_profile_id AND user_id=owner AND status='enabled') THEN
   RAISE EXCEPTION 'Eligible identity and current Creator Terms required' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_guard_course_review_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE s workspace_course_submissions%ROWTYPE; role_value text;
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Workspace review events are append-only' USING ERRCODE = '23514'; END IF;
  SELECT role INTO role_value FROM users WHERE id = NEW.actor_admin_user_id FOR SHARE;
  IF role_value IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Persisted admin required' USING ERRCODE = '23514'; END IF;
  PERFORM id FROM workspace_course_drafts WHERE id = (SELECT draft_id FROM workspace_course_submissions WHERE id = NEW.submission_id) FOR UPDATE;
  SELECT * INTO s FROM workspace_course_submissions WHERE id = NEW.submission_id FOR UPDATE;
  IF s.id IS NULL OR NEW.from_status <> s.review_status OR NEW.transition_version <> s.version + 1 OR NEW.created_at < s.updated_at THEN
    RAISE EXCEPTION 'Stale Workspace review event' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.workspace_guard_course_submission()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d workspace_course_drafts%ROWTYPE; prior workspace_course_submissions%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Workspace submissions must be retained' USING ERRCODE = '23514'; END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO d FROM workspace_course_drafts WHERE id = NEW.draft_id FOR UPDATE;
    SELECT * INTO prior FROM workspace_course_submissions WHERE draft_id = NEW.draft_id ORDER BY submission_number DESC LIMIT 1;
    IF d.id IS NULL OR NEW.user_id <> d.user_id OR NEW.creator_profile_id <> d.creator_profile_id
      OR NEW.draft_version <> d.version OR NEW.review_status <> 'submitted' OR NEW.version <> 1
      OR NEW.submission_number <> coalesce(prior.submission_number, 0) + 1
      OR (prior.id IS NOT NULL AND prior.review_status <> 'changes_requested')
      OR ROW(NEW.title, NEW.category, NEW.description, NEW.target_learner, NEW.learning_outcomes, NEW.outline, NEW.tentative_price_paise, NEW.currency)
        IS DISTINCT FROM ROW(d.title, d.category, d.description, d.target_learner, d.learning_outcomes, d.outline, d.tentative_price_paise, d.currency)
      OR (prior.id IS NOT NULL AND (NEW.content_hash = prior.content_hash OR
        ROW(NEW.title, NEW.category, NEW.description, NEW.target_learner, NEW.learning_outcomes, NEW.outline, NEW.tentative_price_paise, NEW.currency)
          IS NOT DISTINCT FROM ROW(prior.title, prior.category, prior.description, prior.target_learner, prior.learning_outcomes, prior.outline, prior.tentative_price_paise, prior.currency))) THEN
      RAISE EXCEPTION 'Invalid Workspace submission source or sequence' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  -- All fields except lifecycle are immutable, including request/hash/identity/created time.
  IF (to_jsonb(NEW) - ARRAY['review_status','version','review_started_at','review_completed_at','updated_at'])
      IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['review_status','version','review_started_at','review_completed_at','updated_at'])
    OR NEW.version <> OLD.version + 1 OR NEW.updated_at < OLD.updated_at
    OR NOT ((OLD.review_status = 'submitted' AND NEW.review_status = 'under_review' AND NEW.review_started_at = NEW.updated_at AND NEW.review_completed_at IS NULL)
      OR (OLD.review_status = 'under_review' AND NEW.review_status IN ('changes_requested','approved') AND NEW.review_started_at IS NOT DISTINCT FROM OLD.review_started_at AND NEW.review_completed_at = NEW.updated_at)) THEN
    RAISE EXCEPTION 'Invalid immutable Workspace review transition' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.workspace_guard_creator_content()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Workspace creator content must be retained' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.version <> 1 OR NEW.updated_at <> NEW.created_at THEN
      RAISE EXCEPTION 'Invalid initial Workspace content version' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id
    OR NEW.creator_profile_id IS DISTINCT FROM OLD.creator_profile_id
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.version <> OLD.version + 1 OR NEW.updated_at < OLD.updated_at THEN
    RAISE EXCEPTION 'Invalid Workspace content ownership or version transition' USING ERRCODE = '23514';
  END IF;
  IF TG_TABLE_NAME = 'workspace_course_drafts' THEN
    IF NEW.request_key IS DISTINCT FROM OLD.request_key OR NEW.creation_hash IS DISTINCT FROM OLD.creation_hash THEN
      RAISE EXCEPTION 'Workspace creation request is immutable' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.workspace_guard_review_locked_draft()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE latest_status text;
BEGIN
  SELECT review_status INTO latest_status FROM workspace_course_submissions WHERE draft_id = OLD.id ORDER BY submission_number DESC LIMIT 1;
  IF latest_status IN ('submitted','under_review','approved') THEN
    RAISE EXCEPTION 'Workspace draft is review-locked' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.workspace_influencer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Influencer identity is historical' USING ERRCODE='23514'; END IF;
 PERFORM id FROM users WHERE id=NEW.updated_by AND role='admin' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Persisted admin required' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.version<>1 OR NEW.created_by<>NEW.updated_by THEN RAISE EXCEPTION 'Invalid influencer origin' USING ERRCODE='23514'; END IF;
 ELSE
   IF NEW.id<>OLD.id OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1 OR NEW.updated_at<=OLD.updated_at THEN
     RAISE EXCEPTION 'Influencer origin/version is immutable' USING ERRCODE='23514';
   END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_membership_refund_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM id FROM workspace_membership_orders WHERE id=NEW.membership_order_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM workspace_refund_completions WHERE membership_order_id=NEW.membership_order_id) THEN RAISE EXCEPTION 'Refunded payment cannot grant a new membership' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.workspace_phase13_version_pointer_only()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Published Workspace versions cannot be deleted' USING ERRCODE = '23514';
  END IF;
  IF (to_jsonb(NEW) - 'is_current') IS DISTINCT FROM (to_jsonb(OLD) - 'is_current') THEN
    RAISE EXCEPTION 'Publish a new Workspace version instead of editing history' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.workspace_phase14_applicability_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Coupon applicability is immutable' USING ERRCODE = '23514'; END IF;
  PERFORM id FROM workspace_coupons WHERE id = NEW.coupon_id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM workspace_audit_events WHERE coupon_id = NEW.coupon_id AND action = 'coupon_created') THEN
    RAISE EXCEPTION 'Create a new coupon for different applicability' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.workspace_phase14_coupon_complete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE expected_action text; expected_before text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    expected_action := 'coupon_created'; expected_before := NULL;
    IF NEW.status <> 'active' OR NEW.version <> 1 OR NOT EXISTS (SELECT 1 FROM workspace_coupon_plans WHERE coupon_id = NEW.id) OR EXISTS (
      SELECT 1 FROM workspace_coupon_plans cp LEFT JOIN workspace_membership_plans p ON p.code = cp.plan_code AND p.is_current
      WHERE cp.coupon_id = NEW.id AND (p.id IS NULL OR
        CASE WHEN NEW.discount_type = 'fixed' THEN NEW.discount_value ELSE round(p.base_price_paise::numeric * NEW.discount_value / 10000) END >= p.base_price_paise)
    ) THEN RAISE EXCEPTION 'Coupon must have applicable current plans and a positive paid base' USING ERRCODE = '23514'; END IF;
  ELSE
    expected_action := 'coupon_status_changed'; expected_before := OLD.status;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM workspace_audit_events WHERE coupon_id = NEW.id
    AND action = expected_action AND after_status = NEW.status
    AND before_status IS NOT DISTINCT FROM expected_before AND created_at = NEW.updated_at) THEN
    RAISE EXCEPTION 'Coupon creation/status change requires audit evidence in the same transaction' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.workspace_phase14_coupon_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Archive Workspace coupons instead of deleting' USING ERRCODE = '23514'; END IF;
  IF (to_jsonb(NEW) - ARRAY['status','version','updated_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status','version','updated_at'])
    OR OLD.status = 'archived' OR NEW.status = OLD.status OR NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'Coupon definitions are immutable; only versioned status transitions are allowed' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.workspace_phase14_plan_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Workspace plan history is immutable' USING ERRCODE = '23514'; END IF;
  IF (to_jsonb(NEW) - 'is_current') IS DISTINCT FROM (to_jsonb(OLD) - 'is_current') THEN
    RAISE EXCEPTION 'Publish a successor plan version; historical definitions are immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.workspace_phase15_event_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Payment inbox evidence cannot be deleted' USING ERRCODE='23514'; END IF;
  IF (to_jsonb(NEW)-ARRAY['processing_state','processed_at','lease_until','next_attempt_at','attempt_count','last_error_code','anomaly_hash','membership_order_id']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['processing_state','processed_at','lease_until','next_attempt_at','attempt_count','last_error_code','anomaly_hash','membership_order_id']) OR NEW.attempt_count<OLD.attempt_count
     OR (OLD.anomaly_hash IS NOT NULL AND NEW.anomaly_hash IS DISTINCT FROM OLD.anomaly_hash) THEN
    RAISE EXCEPTION 'Payment inbox identity/evidence is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_phase15_financial_complete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE order_id uuid; o workspace_membership_orders; p workspace_payment_attempts; r workspace_coupon_redemptions;
BEGIN
  IF TG_TABLE_NAME='workspace_membership_orders' THEN order_id := NEW.id; ELSE order_id := NEW.membership_order_id; END IF;
  SELECT * INTO o FROM workspace_membership_orders WHERE id=order_id;
  IF o.id IS NULL THEN RAISE EXCEPTION 'Financial order missing' USING ERRCODE='23514'; END IF;
  IF o.financial_state='captured' THEN
    SELECT * INTO p FROM workspace_payment_attempts WHERE membership_order_id=o.id AND provider_payment_id=o.winning_payment_id AND winner;
    IF p.id IS NULL OR p.state<>'captured' OR p.amount_paise<>o.total_paise OR p.currency<>o.currency OR p.user_id<>o.user_id OR p.provider_order_id IS DISTINCT FROM o.provider_order_id
      OR p.provider_account_id<>o.provider_account_id OR p.provider_mode<>o.provider_mode OR (o.paid_at IS NOT NULL AND o.paid_at IS DISTINCT FROM p.captured_at) THEN
      RAISE EXCEPTION 'Captured order requires exact winning payment evidence' USING ERRCODE='23514';
    END IF;
  ELSIF EXISTS(SELECT 1 FROM workspace_payment_attempts WHERE membership_order_id=o.id AND winner) THEN
    RAISE EXCEPTION 'Winning payment requires captured financial order' USING ERRCODE='23514';
  END IF;
  IF o.coupon_id IS NOT NULL THEN
    SELECT * INTO r FROM workspace_coupon_redemptions WHERE membership_order_id=o.id;
    IF r.id IS NULL OR r.user_id<>o.user_id OR r.coupon_id<>o.coupon_id
      OR (o.financial_state='captured' AND r.status<>'redeemed' AND o.review_reason IS DISTINCT FROM 'reservation_inconsistent'
        AND NOT (r.status='reserved' AND o.activation_state='held_for_review'))
      OR (o.financial_state='unpaid' AND o.provider_setup_state<>'closed' AND r.status<>'reserved')
      OR (o.financial_state='unpaid' AND o.provider_setup_state='closed' AND r.status<>'released') THEN
      RAISE EXCEPTION 'Order and coupon financial ledger must commit together' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_phase15_order_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a workspace_eligibility_attempts; p workspace_membership_plans; c workspace_coupons; s workspace_eligibility_settings; v workspace_policy_versions; expected_discount integer;
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Workspace financial history cannot be deleted' USING ERRCODE='23514'; END IF;
  IF TG_OP = 'INSERT' THEN
    PERFORM id FROM users WHERE id=NEW.user_id FOR UPDATE;
    IF NEW.coupon_id IS NOT NULL THEN SELECT * INTO c FROM workspace_coupons WHERE id=NEW.coupon_id FOR UPDATE; END IF;
    SELECT * INTO a FROM workspace_eligibility_attempts WHERE id=NEW.eligibility_attempt_id;
    SELECT * INTO p FROM workspace_membership_plans WHERE id=NEW.plan_version_id FOR SHARE;
    SELECT * INTO s FROM workspace_eligibility_settings WHERE id=NEW.settings_id FOR SHARE;
    SELECT * INTO v FROM workspace_policy_versions WHERE id=NEW.policy_id FOR SHARE;
    IF s.id IS NULL OR NOT s.is_current OR v.id IS NULL OR NOT v.is_current OR v.version<>'workspace-eligibility-declarations-v1'
      OR NEW.launch_at IS DISTINCT FROM (s.config->>'launchAt')::timestamptz
      OR NEW.quote_version<>'workspace-pricing-v1' OR NEW.pricing_rule_version<>'workspace-pricing-v1' OR NEW.membership_start_rule_version<>'workspace-membership-start-v1' THEN
      RAISE EXCEPTION 'Accepted settings/policy/start context mismatch' USING ERRCODE='23514';
    END IF;
    IF a.id IS NULL OR a.user_id <> NEW.user_id OR a.result <> 'eligible' OR a.eligible_until IS DISTINCT FROM NEW.eligibility_valid_until OR a.eligible_until <= NEW.created_at
      OR p.id IS NULL OR NOT p.is_current OR NOT p.available OR p.code <> NEW.plan_code OR p.base_price_paise <> NEW.base_price_paise OR p.duration_months <> NEW.duration_months
      OR NEW.plan_snapshot IS DISTINCT FROM jsonb_build_object('version',p.version,'displayName',p.display_name)
      OR NEW.provider_setup_state <> 'creating' OR NEW.provider_request_count <> 0 OR NEW.financial_state <> 'unpaid' OR NEW.activation_state <> 'pending_activation' OR NEW.version <> 1 THEN
      RAISE EXCEPTION 'Accepted order owner/context/state mismatch' USING ERRCODE='23514';
    END IF;
    IF NEW.coupon_id IS NOT NULL THEN
      expected_discount := CASE WHEN c.discount_type='fixed' THEN c.discount_value ELSE round(p.base_price_paise::numeric*c.discount_value/10000)::integer END;
      IF c.id IS NULL OR c.status <> 'active' OR c.code <> NEW.coupon_code OR (c.starts_at IS NOT NULL AND NEW.created_at<c.starts_at) OR (c.expires_at IS NOT NULL AND NEW.created_at>=c.expires_at)
        OR NOT EXISTS(SELECT 1 FROM workspace_coupon_plans WHERE coupon_id=c.id AND plan_code=p.code) OR expected_discount <> NEW.discount_paise
        OR NEW.coupon_snapshot IS DISTINCT FROM jsonb_build_object('campaignName',c.campaign_name,'sourceType',c.source_type,'sourceName',c.source_name,'discountType',c.discount_type,'discountValue',c.discount_value,'version',c.version,'usageLimit',c.usage_limit) THEN
        RAISE EXCEPTION 'Accepted coupon snapshot mismatch' USING ERRCODE='23514';
      END IF;
    END IF;
  ELSE
    IF (to_jsonb(NEW)-ARRAY['provider_setup_state','provider_create_started_at','provider_request_count','provider_order_id','provider_order_created_at','provider_recovery_checked_at','provider_recovery_reason','provider_create_failure_hash','financial_state','activation_state','winning_payment_id','paid_at','refund_eligible_until','review_reason','closed_at','close_reason','version','fulfilled_at']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['provider_setup_state','provider_create_started_at','provider_request_count','provider_order_id','provider_order_created_at','provider_recovery_checked_at','provider_recovery_reason','provider_create_failure_hash','financial_state','activation_state','winning_payment_id','paid_at','refund_eligible_until','review_reason','closed_at','close_reason','version','fulfilled_at'])
       OR (OLD.fulfilled_at IS NOT NULL AND (NEW.fulfilled_at IS DISTINCT FROM OLD.fulfilled_at OR NEW.activation_state NOT IN ('fulfilled','held_for_review')))
       OR NEW.version <> OLD.version+1 OR NEW.provider_request_count < OLD.provider_request_count
       OR (OLD.provider_create_started_at IS NOT NULL AND NEW.provider_create_started_at IS DISTINCT FROM OLD.provider_create_started_at)
       OR (OLD.provider_order_id IS NOT NULL AND (NEW.provider_order_id IS DISTINCT FROM OLD.provider_order_id OR NEW.provider_order_created_at IS DISTINCT FROM OLD.provider_order_created_at))
       OR (OLD.provider_create_failure_hash IS NOT NULL AND NEW.provider_create_failure_hash IS DISTINCT FROM OLD.provider_create_failure_hash)
       OR (OLD.financial_state='captured' AND (NEW.financial_state<>'captured' OR NEW.winning_payment_id IS DISTINCT FROM OLD.winning_payment_id))
       OR (OLD.paid_at IS NOT NULL AND (NEW.paid_at IS DISTINCT FROM OLD.paid_at OR NEW.refund_eligible_until IS DISTINCT FROM OLD.refund_eligible_until))
       OR (OLD.provider_setup_state='closed' AND NEW.provider_setup_state<>'closed') THEN
      RAISE EXCEPTION 'Workspace accepted economics/provider/capture history is immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.provider_setup_state='closed' AND (NEW.provider_order_id IS NOT NULL OR NEW.financial_state <> 'unpaid'
      OR (NEW.close_reason='never_submitted' AND NEW.provider_create_started_at IS NOT NULL)
      OR (NEW.close_reason='provider_definitive_rejection' AND (NEW.provider_request_count<>1 OR NEW.provider_create_failure_hash IS NULL))) THEN
    RAISE EXCEPTION 'Provider-backed or ambiguous checkout cannot be released on a timer' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_phase15_redemption_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c workspace_coupons; o workspace_membership_orders; occupied bigint;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Coupon financial ledger is historical' USING ERRCODE='23514'; END IF;
  PERFORM id FROM users WHERE id=NEW.user_id FOR UPDATE;
  SELECT * INTO c FROM workspace_coupons WHERE id=NEW.coupon_id FOR UPDATE;
  SELECT * INTO o FROM workspace_membership_orders WHERE id=NEW.membership_order_id;
  IF o.id IS NULL OR o.user_id<>NEW.user_id OR o.coupon_id IS DISTINCT FROM NEW.coupon_id THEN
    RAISE EXCEPTION 'Reservation owner/coupon mismatch' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.status <> 'reserved' OR c.status<>'active' OR (c.starts_at IS NOT NULL AND NEW.reserved_at<c.starts_at) OR (c.expires_at IS NOT NULL AND NEW.reserved_at>=c.expires_at) THEN
      RAISE EXCEPTION 'New coupon reservation is not available' USING ERRCODE='23514';
    END IF;
  ELSE
    IF (to_jsonb(NEW)-ARRAY['status','redeemed_at','released_at','release_reason','release_evidence_hash','release_source']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['status','redeemed_at','released_at','release_reason','release_evidence_hash','release_source']) OR OLD.status<>'reserved' OR NEW.status NOT IN ('redeemed','released') THEN
      RAISE EXCEPTION 'Coupon reservation transition/history is immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.status IN ('reserved','redeemed') AND c.usage_limit IS NOT NULL THEN
    SELECT count(*) INTO occupied FROM workspace_coupon_redemptions WHERE coupon_id=NEW.coupon_id AND status IN ('reserved','redeemed') AND id<>NEW.id;
    IF occupied+1>c.usage_limit THEN RAISE EXCEPTION 'Workspace coupon capacity exhausted' USING ERRCODE='23514'; END IF;
  END IF;
  IF NEW.status='released' AND (o.provider_setup_state<>'closed' OR o.financial_state<>'unpaid' OR o.provider_order_id IS NOT NULL OR o.close_reason IS DISTINCT FROM NEW.release_reason
    OR (NEW.release_reason='never_submitted' AND o.provider_create_started_at IS NOT NULL) OR (NEW.release_reason='provider_definitive_rejection' AND (o.provider_request_count<>1 OR o.provider_create_failure_hash IS NULL OR o.provider_create_failure_hash IS DISTINCT FROM NEW.release_evidence_hash))) THEN
    RAISE EXCEPTION 'Coupon hold release requires proven pre-provider rejection/closure' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_phase15b_complete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE o workspace_membership_orders; m workspace_memberships;
BEGIN
 IF TG_TABLE_NAME='workspace_creator_profiles' THEN
   IF NOT EXISTS(SELECT 1 FROM workspace_memberships WHERE creator_profile_id=NEW.id AND user_id=NEW.user_id AND fulfilled_at=NEW.created_at) AND NOT EXISTS(SELECT 1 FROM workspace_access_grants WHERE creator_profile_id=NEW.id AND user_id=NEW.user_id AND created_at=NEW.created_at) THEN
     RAISE EXCEPTION 'Creator identity must commit with membership fulfillment or audited administrative grant' USING ERRCODE='23514';
   END IF;
   RETURN NULL;
 END IF;
 IF TG_TABLE_NAME='workspace_membership_orders' THEN SELECT * INTO o FROM workspace_membership_orders WHERE id=NEW.id;
 ELSE SELECT * INTO o FROM workspace_membership_orders WHERE id=NEW.membership_order_id; END IF;
 SELECT * INTO m FROM workspace_memberships WHERE membership_order_id=o.id;
 IF (o.fulfilled_at IS NULL AND m.id IS NOT NULL) OR (o.fulfilled_at IS NOT NULL AND
   (m.id IS NULL OR m.fulfilled_at IS DISTINCT FROM o.fulfilled_at OR m.user_id<>o.user_id OR m.paid_at IS DISTINCT FROM o.paid_at OR m.plan_version_id<>o.plan_version_id OR m.duration_months<>o.duration_months)) THEN
   RAISE EXCEPTION 'Order and immutable membership fulfillment must commit together' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_phase15b_membership_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE o workspace_membership_orders; p workspace_payment_attempts; c workspace_creator_profiles; expected_start timestamptz; expected_end timestamptz;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Membership terms and fulfillment history are immutable' USING ERRCODE='23514'; END IF;
 -- Serialize every initial fulfillment for the persisted owner. No extension or reset is necessary.
 PERFORM id FROM users WHERE id=NEW.user_id FOR UPDATE;
 SELECT * INTO o FROM workspace_membership_orders WHERE id=NEW.membership_order_id FOR UPDATE;
 SELECT * INTO c FROM workspace_creator_profiles WHERE id=NEW.creator_profile_id FOR UPDATE;
 SELECT * INTO p FROM workspace_payment_attempts WHERE membership_order_id=o.id AND provider_payment_id=o.winning_payment_id AND winner;
 IF o.id IS NULL OR c.id IS NULL OR c.user_id<>NEW.user_id OR c.status<>'enabled' OR o.user_id<>NEW.user_id
   OR o.activation_state<>'pending_activation' OR o.fulfilled_at IS NOT NULL OR o.review_reason IS NOT NULL OR o.financial_state<>'captured' OR o.provider_setup_state<>'ready'
   OR o.paid_at IS NULL OR o.refund_eligible_until IS DISTINCT FROM o.paid_at+interval '72 hours' OR o.paid_at<o.created_at OR o.paid_at>=o.eligibility_valid_until
   OR o.plan_version_id<>NEW.plan_version_id OR o.duration_months<>NEW.duration_months OR o.paid_at IS DISTINCT FROM NEW.paid_at
   OR o.launch_at IS DISTINCT FROM '2026-11-08T18:30:00.000Z'::timestamptz OR o.membership_start_rule_version<>'workspace-membership-start-v1'
   OR o.membership_start_rule IS DISTINCT FROM 'If payment is completed before 9 November 2026 at 00:00 IST, your paid membership term starts at launch. If payment is completed on or after launch, your membership starts on the successful payment date.'
   OR NOT ((o.provider_mode='test' AND o.commercial_policy_version='workspace-test-noncommercial-v1') OR (o.provider_mode='live' AND o.commercial_policy_version='workspace-live-commercial-v1'))
   OR (o.provider_mode='live' AND p.capture_time_source IS DISTINCT FROM 'razorpay_payment_captured_event_v1')
   OR p.id IS NULL OR p.state<>'captured' OR p.refunded_paise<>0 OR (p.capture_time_source IS NULL OR p.capture_time_source NOT IN ('test_authoritative','razorpay_payment_captured_event_v1'))
   OR (p.capture_time_source='razorpay_payment_captured_event_v1' AND NOT EXISTS (
     SELECT 1 FROM workspace_payment_events e WHERE e.provider_account_id=p.provider_account_id AND e.provider_mode=p.provider_mode
       AND e.event_type='payment.captured' AND e.anomaly_hash IS NULL
       AND e.evidence->>'providerOrderId'=p.provider_order_id AND e.evidence->>'providerPaymentId'=p.provider_payment_id
       AND (e.evidence->>'eventCreatedAt')::timestamptz=p.captured_at AND p.captured_at<=e.received_at))
   OR p.captured_at IS DISTINCT FROM o.paid_at OR p.provider_created_at>o.paid_at OR p.user_id<>o.user_id OR p.provider_order_id IS DISTINCT FROM o.provider_order_id
   OR p.provider_account_id<>o.provider_account_id OR p.provider_mode<>o.provider_mode OR p.amount_paise<>o.total_paise OR p.currency<>o.currency
   OR (o.coupon_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM workspace_coupon_redemptions WHERE membership_order_id=o.id AND user_id=o.user_id AND coupon_id=o.coupon_id AND status='redeemed')) THEN
   RAISE EXCEPTION 'Membership requires safe captured evidence and enabled matching creator' USING ERRCODE='23514';
 END IF;
 expected_start := greatest(o.paid_at, o.launch_at);
 expected_end := ((expected_start AT TIME ZONE 'Asia/Kolkata') + make_interval(months=>o.duration_months)) AT TIME ZONE 'Asia/Kolkata';
 IF NEW.starts_at IS DISTINCT FROM expected_start OR NEW.ends_at IS DISTINCT FROM expected_end OR
    EXISTS(SELECT 1 FROM workspace_memberships WHERE user_id=NEW.user_id AND (ends_at>NEW.fulfilled_at OR (starts_at<NEW.ends_at AND NEW.starts_at<ends_at))) THEN
   RAISE EXCEPTION 'Membership term mismatch or overlapping initial membership' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_phase15b_profile_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Creator identity history cannot be deleted' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
   PERFORM id FROM users WHERE id=NEW.user_id FOR UPDATE;
   IF NEW.status<>'enabled' THEN RAISE EXCEPTION 'New creator must be enabled by fulfillment' USING ERRCODE='23514'; END IF;
 ELSIF (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status') OR
   (OLD.status='terminated' AND NEW.status<>'terminated') OR (OLD.status='suspended' AND NEW.status='enabled') THEN
   RAISE EXCEPTION 'Creator identity is immutable; fulfillment cannot re-enable a profile' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.workspace_refund_approval_complete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM workspace_refund_requests r WHERE r.id=NEW.id AND r.decision='approved' AND NOT EXISTS(SELECT 1 FROM workspace_refund_attempts a WHERE a.request_id=r.id)) THEN
  RAISE EXCEPTION 'Refund approval must commit a durable provider intent' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.workspace_refund_attempt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE o workspace_membership_orders; r workspace_refund_requests;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Refund attempts cannot be deleted' USING ERRCODE='23514'; END IF;
 SELECT * INTO o FROM workspace_membership_orders WHERE id=NEW.membership_order_id FOR UPDATE;
 SELECT * INTO r FROM workspace_refund_requests WHERE id=NEW.request_id;
 IF r.id IS NULL OR r.decision<>'approved' OR NEW.user_id IS DISTINCT FROM o.user_id OR NEW.membership_order_id IS DISTINCT FROM r.membership_order_id
  OR NEW.provider_account_id IS DISTINCT FROM o.provider_account_id OR NEW.provider_mode IS DISTINCT FROM o.provider_mode OR NEW.provider_payment_id IS DISTINCT FROM o.winning_payment_id
  OR NEW.amount_paise IS DISTINCT FROM o.total_paise OR NEW.currency IS DISTINCT FROM o.currency THEN
  RAISE EXCEPTION 'Refund attempt must match approved full payment' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'prepared' OR NEW.started_at IS NOT NULL OR NEW.provider_refund_id IS NOT NULL OR NEW.evidence_hash IS NOT NULL THEN RAISE EXCEPTION 'Refund intent must be prepared before submission' USING ERRCODE='23514'; END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['state','provider_refund_id','started_at','last_checked_at','evidence_hash','error_code']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','provider_refund_id','started_at','last_checked_at','evidence_hash','error_code'])
   OR OLD.state='completed' OR (OLD.provider_refund_id IS NOT NULL AND NEW.provider_refund_id IS DISTINCT FROM OLD.provider_refund_id)
   OR (NEW.state='prepared' AND NOT (OLD.state='failed' AND OLD.error_code='definitive_rejection' AND OLD.provider_refund_id IS NULL))
   OR (OLD.state='prepared' AND NEW.state NOT IN ('uncertain','completed'))
   OR (NEW.started_at IS DISTINCT FROM OLD.started_at AND NOT ((OLD.state='prepared' AND NEW.state='uncertain' AND NEW.started_at IS NOT NULL) OR (OLD.state='failed' AND OLD.error_code='definitive_rejection' AND NEW.state='prepared' AND NEW.started_at IS NULL))) THEN
    RAISE EXCEPTION 'Invalid refund execution transition or identity rewrite' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.state='completed' AND NOT EXISTS(SELECT 1 FROM workspace_refund_completions c WHERE c.membership_order_id=o.id AND c.provider_refund_id=NEW.provider_refund_id AND c.evidence_hash=NEW.evidence_hash) THEN
  RAISE EXCEPTION 'Completed attempt requires authoritative full-refund evidence' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.workspace_refund_delivery_attempt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d workspace_refund_notice_deliveries;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Notice attempts cannot be deleted' USING ERRCODE='23514'; END IF;
 SELECT * INTO d FROM workspace_refund_notice_deliveries WHERE id=NEW.delivery_id FOR UPDATE;
 IF d.id IS NULL THEN RAISE EXCEPTION 'Notice attempt requires delivery' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF d.state NOT IN ('pending','retryable_failure') OR d.attempt_count>=5 OR NEW.attempt_number<>d.attempt_count+1 OR NEW.state<>'claimed' OR NEW.dispatch_at IS NOT NULL OR NEW.finished_at IS NOT NULL OR NEW.reason_code IS NOT NULL OR NEW.provider_code IS NOT NULL OR NEW.provider_reference IS NOT NULL OR NEW.payload_hash IS NOT NULL OR NEW.recipient_hash IS NOT NULL OR NEW.provider_config_hash IS NOT NULL OR NEW.template_version IS NOT NULL THEN
   RAISE EXCEPTION 'Notice attempt must begin claimed' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.state IN ('accepted','retryable_failure','uncertain','blocked') AND (NEW.finished_at IS NULL OR NEW.finished_at<coalesce(OLD.dispatch_at,OLD.created_at) OR NEW.reason_code IS NULL) THEN RAISE EXCEPTION 'Terminal attempt requires dated evidence' USING ERRCODE='23514'; END IF;
 IF OLD.state IN ('accepted','retryable_failure','uncertain','blocked') OR d.current_attempt_id IS DISTINCT FROM OLD.id OR d.state IS DISTINCT FROM OLD.state
  OR (to_jsonb(NEW)-ARRAY['state','dispatch_at','finished_at','reason_code','provider_code','provider_reference','payload_hash','recipient_hash','provider_config_hash','template_version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','dispatch_at','finished_at','reason_code','provider_code','provider_reference','payload_hash','recipient_hash','provider_config_hash','template_version'])
  OR NOT ((OLD.state='claimed' AND NEW.state IN ('submitted','retryable_failure','blocked')) OR (OLD.state='submitted' AND NEW.state IN ('accepted','retryable_failure','uncertain','blocked'))) THEN
   RAISE EXCEPTION 'Notice attempt history or stale result cannot be rewritten' USING ERRCODE='23514';
 END IF;
 IF OLD.state='submitted' AND (NEW.dispatch_at IS DISTINCT FROM OLD.dispatch_at OR NEW.payload_hash IS DISTINCT FROM OLD.payload_hash OR NEW.recipient_hash IS DISTINCT FROM OLD.recipient_hash OR NEW.provider_config_hash IS DISTINCT FROM OLD.provider_config_hash OR NEW.template_version IS DISTINCT FROM OLD.template_version) THEN RAISE EXCEPTION 'Submitted notice payload is immutable' USING ERRCODE='23514'; END IF;
 IF NEW.state='submitted' AND (d.lease_until<=clock_timestamp() OR NEW.dispatch_at IS NULL OR NEW.payload_hash IS NULL OR NEW.recipient_hash IS NULL OR NEW.provider_config_hash IS NULL OR NEW.template_version IS NULL) THEN RAISE EXCEPTION 'Submission requires current lease and pinned payload' USING ERRCODE='23514'; END IF;
 IF NEW.state='accepted' AND (NEW.provider_code IS DISTINCT FROM 1000 OR NEW.reason_code IS DISTINCT FROM 'provider_accepted') THEN RAISE EXCEPTION 'Provider acceptance receipt required' USING ERRCODE='23514'; END IF;
 IF NEW.state='retryable_failure' AND NEW.reason_code NOT IN ('not_dispatched','lease_expired_before_dispatch','provider_throttled') THEN RAISE EXCEPTION 'Ambiguous sends cannot be blindly retried' USING ERRCODE='23514'; END IF;
 IF OLD.state='submitted' AND NEW.state='retryable_failure' AND NEW.reason_code='lease_expired_before_dispatch' THEN RAISE EXCEPTION 'Dispatched lease expiry is uncertain' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.workspace_refund_delivery_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a workspace_refund_notice_delivery_attempts;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Refund delivery history cannot be deleted' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'pending' OR NEW.version<>1 OR NEW.attempt_count<>0 OR NEW.current_attempt_id IS NOT NULL OR NEW.lease_until IS NOT NULL OR NEW.next_attempt_at IS NOT NULL OR NEW.reason_code IS NOT NULL OR NEW.payload_hash IS NOT NULL OR NEW.recipient_hash IS NOT NULL OR NEW.provider_config_hash IS NOT NULL OR NEW.template_version IS NOT NULL OR NEW.accepted_at IS NOT NULL OR NEW.created_at IS DISTINCT FROM NEW.updated_at THEN
   RAISE EXCEPTION 'Notice delivery must begin pending' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.state IN ('accepted','uncertain','blocked') OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at OR NEW.updated_at>clock_timestamp()
  OR (to_jsonb(NEW)-ARRAY['state','current_attempt_id','lease_until','attempt_count','next_attempt_at','reason_code','payload_hash','recipient_hash','provider_config_hash','template_version','accepted_at','updated_at','version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','current_attempt_id','lease_until','attempt_count','next_attempt_at','reason_code','payload_hash','recipient_hash','provider_config_hash','template_version','accepted_at','updated_at','version'])
  OR (OLD.payload_hash IS NOT NULL AND (NEW.payload_hash IS DISTINCT FROM OLD.payload_hash OR NEW.recipient_hash IS DISTINCT FROM OLD.recipient_hash OR NEW.provider_config_hash IS DISTINCT FROM OLD.provider_config_hash OR NEW.template_version IS DISTINCT FROM OLD.template_version)) THEN
   RAISE EXCEPTION 'Notice identity, pinned payload and terminal history are immutable' USING ERRCODE='23514';
 END IF;
 IF NOT ((OLD.state IN ('pending','retryable_failure') AND NEW.state='claimed') OR (OLD.state='claimed' AND NEW.state IN ('submitted','retryable_failure','blocked')) OR (OLD.state='submitted' AND NEW.state IN ('accepted','retryable_failure','uncertain','blocked'))) THEN
  RAISE EXCEPTION 'Invalid notice delivery transition' USING ERRCODE='23514';
 END IF;
 SELECT * INTO a FROM workspace_refund_notice_delivery_attempts WHERE id=NEW.current_attempt_id AND delivery_id=NEW.id;
 IF a.id IS NULL OR a.state IS DISTINCT FROM NEW.state OR a.attempt_number<>NEW.attempt_count THEN RAISE EXCEPTION 'Delivery requires matching current attempt' USING ERRCODE='23514'; END IF;
 IF NEW.state='claimed' THEN
  IF NEW.attempt_count<>OLD.attempt_count+1 OR OLD.attempt_count>=5 OR NEW.current_attempt_id IS NOT DISTINCT FROM OLD.current_attempt_id OR NEW.lease_until<=clock_timestamp() OR NEW.lease_until>clock_timestamp()+interval '60 seconds' OR NEW.next_attempt_at IS NOT NULL THEN
   RAISE EXCEPTION 'Invalid bounded notice claim' USING ERRCODE='23514';
  END IF;
 ELSE
  IF NEW.current_attempt_id IS DISTINCT FROM OLD.current_attempt_id OR NEW.attempt_count<>OLD.attempt_count THEN RAISE EXCEPTION 'Stale notice claim' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.state='submitted' AND (OLD.lease_until<=clock_timestamp() OR NEW.lease_until IS DISTINCT FROM OLD.lease_until OR NEW.payload_hash IS NULL OR NEW.recipient_hash IS NULL OR NEW.provider_config_hash IS NULL OR NEW.template_version IS NULL OR a.payload_hash IS DISTINCT FROM NEW.payload_hash OR a.recipient_hash IS DISTINCT FROM NEW.recipient_hash OR a.provider_config_hash IS DISTINCT FROM NEW.provider_config_hash OR a.template_version IS DISTINCT FROM NEW.template_version) THEN
  RAISE EXCEPTION 'Dispatch requires an unexpired pinned claim' USING ERRCODE='23514';
 END IF;
 IF NEW.state='accepted' AND (a.provider_code IS DISTINCT FROM 1000 OR a.reason_code IS DISTINCT FROM 'provider_accepted' OR a.dispatch_at IS NULL OR NEW.accepted_at IS DISTINCT FROM a.finished_at) THEN RAISE EXCEPTION 'Acceptance requires matching provider receipt' USING ERRCODE='23514'; END IF;
 IF NEW.state='retryable_failure' AND (NEW.next_attempt_at IS NULL OR NEW.next_attempt_at<=NEW.updated_at OR NEW.attempt_count>=5) THEN RAISE EXCEPTION 'Retry requires bounded scheduling' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

